package com.mysterymango.game;

import com.mysterymango.common.ApiException;
import org.junit.jupiter.api.Test;
import java.util.*;
import static com.mysterymango.game.Definitions.*;
import static org.junit.jupiter.api.Assertions.*;

class ClassicEngineTest {
    private final BoardEngine engine=new BoardEngine(new Random(1));
    @Test void gomokuEnforcesTurnAndOccupiedCellsAndWinsWithFiveOrOverline(){
        var s=engine.initial("GOMOKU",Map.of(),2);assertEquals(225,objects(engine.project("GOMOKU",s,0).get("legalMoves")).size());assertTrue(objects(engine.project("GOMOKU",s,1).get("legalMoves")).isEmpty());assertThrows(ApiException.class,()->place("GOMOKU",s,1,0,0));
        for(int c=0;c<4;c++){place("GOMOKU",s,0,7,c);place("GOMOKU",s,1,0,c);}assertThrows(ApiException.class,()->place("GOMOKU",s,0,7,0));place("GOMOKU",s,0,7,4);assertEquals(List.of(0),s.get("winners"));assertEquals("FIVE_IN_ROW",s.get("endReason"));assertThrows(ApiException.class,()->place("GOMOKU",s,1,1,0));
        var overline=engine.initial("GOMOKU",Map.of(),2);int[][] board=new int[15][15];for(int c:new int[]{1,2,3,5,6})board[7][c]=1;setBoard(overline,board);place("GOMOKU",overline,0,7,4);assertEquals(List.of(0),overline.get("winners"));assertThrows(ApiException.class,()->engine.initial("GOMOKU",Map.of(),1));
    }
    @Test void reversiFlipsEveryBracketAndRejectsNonCapturingPlacement(){var s=engine.initial("REVERSI",Map.of(),2);assertEquals(4,objects(engine.project("REVERSI",s,0).get("legalMoves")).size());assertThrows(ApiException.class,()->place("REVERSI",s,0,0,0));place("REVERSI",s,0,2,3);assertEquals(List.of(4,1),engine.project("REVERSI",s,1).get("counts"));assertEquals(1,integer(s,"turnSeat",-1));}
    @Test void reversiAutomaticallyPassesAndStopsWhenNeitherSideCanPlace(){var s=engine.initial("REVERSI",Map.of(),2);int[][] board=filled(8,1);board[0][0]=0;board[0][1]=2;board[0][3]=0;board[0][4]=2;setBoard(s,board);place("REVERSI",s,0,0,0);assertEquals(0,integer(s,"turnSeat",-1));assertFalse(bool(s,"finished"));place("REVERSI",s,0,0,3);assertEquals(List.of(0),s.get("winners"));assertEquals("BOARD_FULL",s.get("endReason"));
        var blocked=engine.initial("REVERSI",Map.of(),2);board=filled(8,1);board[0][0]=0;board[0][1]=2;board[7][7]=0;setBoard(blocked,board);place("REVERSI",blocked,0,0,0);assertEquals("NO_LEGAL_MOVES",blocked.get("endReason"));assertEquals(List.of(0),blocked.get("winners"));}
    @Test void reversiTiedFinalCountIsADraw(){var s=engine.initial("REVERSI",Map.of(),2);int[][] board=filled(8,2);board[0][0]=0;board[0][2]=1;board[1][0]=1;board[1][1]=1;int ones=3;for(int r=0;r<8&&ones<30;r++)for(int c=0;c<8&&ones<30;c++)if(!(r==0&&(c==0||c==1))&&board[r][c]==2){board[r][c]=1;ones++;}setBoard(s,board);place("REVERSI",s,0,0,0);assertEquals(List.of(32,32),engine.project("REVERSI",s,0).get("counts"));assertTrue(bool(s,"draw"));assertEquals(List.of(),s.get("winners"));}
    @Test void checkersRequiresCaptureAndFinishesTheCaptureChainWithTheSamePiece(){var s=engine.initial("CHECKERS",Map.of(),2);int[][] board=new int[8][8];board[5][2]=1;board[5][6]=1;board[4][3]=2;board[2][5]=2;board[0][1]=2;setBoard(s,board);s.put("halfMovesWithoutProgress",79);assertThrows(ApiException.class,()->move(s,0,5,6,4,7));move(s,0,5,2,3,4);assertEquals(obj("row",3,"col",4),s.get("forcedFrom"));assertEquals(0,integer(s,"turnSeat",-1));assertEquals(0,integer(s,"halfMovesWithoutProgress",-1));assertThrows(ApiException.class,()->move(s,0,5,6,4,7));move(s,0,3,4,1,6);assertNull(s.get("forcedFrom"));assertEquals(1,integer(s,"turnSeat",-1));assertEquals(List.of(2,1),engine.project("CHECKERS",s,0).get("counts"));}
    @Test void checkersCrowningEndsTurnInsteadOfCapturingBackwardAsANewKing(){var s=engine.initial("CHECKERS",Map.of(),2);int[][] board=new int[8][8];board[2][1]=1;board[1][2]=2;board[1][4]=2;setBoard(s,board);move(s,0,2,1,0,3);assertEquals(3,cell(s,0,3));assertEquals(1,integer(s,"turnSeat",-1));assertNull(s.get("forcedFrom"));assertFalse(bool(s,"finished"));}
    @Test void checkersMenCannotMoveBackwardButKingsCanAndBlockedOpponentLoses(){var s=engine.initial("CHECKERS",Map.of(),2);int[][] board=new int[8][8];board[3][2]=1;board[0][7]=2;setBoard(s,board);assertThrows(ApiException.class,()->move(s,0,3,2,4,3));board[3][2]=3;setBoard(s,board);move(s,0,3,2,4,3);assertEquals(3,cell(s,4,3));
        var blocked=engine.initial("CHECKERS",Map.of(),2);board=new int[8][8];board[2][1]=1;board[7][0]=1;board[7][2]=1;board[5][0]=1;board[5][2]=1;board[6][1]=2;setBoard(blocked,board);move(blocked,0,2,1,1,0);assertEquals(List.of(0),blocked.get("winners"));assertEquals("NO_LEGAL_MOVES",blocked.get("endReason"));}
    @Test void checkersLastCaptureWinsAndNoProgressOrThreefoldDraw(){var capture=engine.initial("CHECKERS",Map.of(),2);int[][] board=new int[8][8];board[5][2]=1;board[4][3]=2;setBoard(capture,board);move(capture,0,5,2,3,4);assertEquals("NO_PIECES",capture.get("endReason"));assertEquals(List.of(0),capture.get("winners"));
        var noProgress=kings();noProgress.put("halfMovesWithoutProgress",79);move(noProgress,0,7,0,6,1);assertEquals("NO_PROGRESS",noProgress.get("endReason"));assertTrue(bool(noProgress,"draw"));
        var repeated=kings();int[][] cycle={{0,7,0,6,1},{1,0,7,1,6},{0,6,1,7,0},{1,1,6,0,7}};for(int step=0;step<12&&!bool(repeated,"finished");step++){var m=cycle[step%4];move(repeated,m[0],m[1],m[2],m[3],m[4]);}assertEquals("REPETITION",repeated.get("endReason"));assertTrue(bool(repeated,"draw"));assertEquals(List.of(),repeated.get("winners"));}
    @Test void resignationAndAbortHaveDifferentResultsAndProjectionHidesInternalCounters(){for(String type:List.of("GOMOKU","REVERSI","CHECKERS")){var s=engine.initial(type,obj("classic",obj("boardColor","#123456","script","ignored")),2);engine.command(type,s,1,false,"LEAVE",Map.of());var result=engine.project(type,s,0);assertEquals(List.of(0),result.get("winners"));assertEquals("RESIGNATION",result.get("endReason"));assertFalse(result.containsKey("repetitions"));assertFalse(map(result.get("appearance")).containsKey("script"));s.put("aborted",true);var aborted=engine.project(type,s,0);assertEquals(List.of(),aborted.get("winners"));assertEquals("ABORTED",aborted.get("endReason"));assertFalse(bool(aborted,"draw"));}}
    private Map<String,Object> kings(){var s=engine.initial("CHECKERS",Map.of(),2);int[][] board=new int[8][8];board[7][0]=3;board[0][7]=4;setBoard(s,board);s.put("repetitions",new LinkedHashMap<String,Object>());return s;}
    private void place(String type,Map<String,Object> state,int seat,int row,int col){engine.command(type,state,seat,seat==0,"PLACE",obj("row",row,"col",col));}
    private void move(Map<String,Object> state,int seat,int fr,int fc,int tr,int tc){engine.command("CHECKERS",state,seat,seat==0,"MOVE",obj("fromRow",fr,"fromCol",fc,"toRow",tr,"toCol",tc));}
    private static int[][] filled(int size,int value){int[][] board=new int[size][size];for(var row:board)Arrays.fill(row,value);return board;}
    private static void setBoard(Map<String,Object> state,int[][] board){state.put("board",Arrays.stream(board).map(row->Arrays.stream(row).boxed().toList()).toList());}
    private static int cell(Map<String,Object> state,int row,int col){return ((Number)((List<?>)((List<?>)state.get("board")).get(row)).get(col)).intValue();}
}
